    app.add_config_value('cpp_debug_show_tree', False, '', types=frozenset({bool}))

    app.connect('builder-inited', _init_stuff)

    return {
        'version': 'builtin',
        'env_version': 9,
        'parallel_read_safe': True,
        'parallel_write_safe': True,
    }

