def _get_full_modname(modname: str, attribute: str) -> str | None:
    if modname is None:
        # Prevents a TypeError: if the last getattr() call will return None
        # then it's better to return it directly
        return None

    try:
        # Attempt to find full path of module
        module_path = modname.split('.')
        num_parts = len(module_path)
        for i in range(num_parts, 0, -1):
            mod_root = '.'.join(module_path[:i])
            try:
                # import_module() caches the module in sys.modules
                module = importlib.import_module(mod_root)
                break
            except ModuleNotFoundError:
                continue
            except BaseException as exc:
                # Importing modules may cause any side effects, including
                # SystemExit, so we need to catch all errors.
                msg = f"viewcode failed to import '{mod_root}'."
                raise ImportError(msg) from exc
        else:
            return None

        if i != num_parts:
            for mod in module_path[i:]:
                module = getattr(module, mod)

        # Allow an attribute to have multiple parts and incidentally allow
        # repeated .s in the attribute.
        value = module
        for attr in attribute.split('.'):
            if attr:
                value = getattr(value, attr)

        return getattr(value, '__module__', None)
    except AttributeError:
        # sphinx.ext.viewcode can't follow class instance attribute
        # then AttributeError logging output only debug mode.
        logger.debug("Didn't find %s in %s", attribute, modname)
        return None
    except Exception as e:
        # sphinx.ext.viewcode follow python domain directives.
        # because of that, if there are no real modules exists that specified
        # by py:function or other directives, viewcode emits a lot of warnings.
        # It should be displayed only verbose mode.
        logger.verbose(traceback.format_exc().rstrip())
        logger.verbose('viewcode can\'t import %s, failed with error "%s"', modname, e)
        return None


def is_supported_builder(builder: type[Builder], viewcode_enable_epub: bool) -> bool:
    return (
        builder.format == 'html'
        and builder.name != 'singlehtml'
        and (not builder.name.startswith('epub') or viewcode_enable_epub)
    )


def doctree_read(app: Sphinx, doctree: Node) -> None:
    env = app.env
    events = app.events
    if not hasattr(env, '_viewcode_modules'):
        env._viewcode_modules = {}  # type: ignore[attr-defined]

    def has_tag(modname: str, fullname: str, docname: str, refname: str) -> bool:
        entry = env._viewcode_modules.get(modname, None)  # type: ignore[attr-defined]
        if entry is False:
            return False

        code_tags = events.emit_firstresult('viewcode-find-source', modname)
        if code_tags is None:
            try:
                analyzer = ModuleAnalyzer.for_module(modname)
                analyzer.find_tags()
            except Exception:
                env._viewcode_modules[modname] = False  # type: ignore[attr-defined]
                return False

            code = analyzer.code
            tags = analyzer.tags
        else:
            code, tags = code_tags

        if entry is None or entry[0] != code:
            entry = code, tags, {}, refname
            env._viewcode_modules[modname] = entry  # type: ignore[attr-defined]
        _, tags, used, _ = entry
        if fullname in tags:
            used[fullname] = docname
            return True

        return False

    for objnode in list(doctree.findall(addnodes.desc)):
        if objnode.get('domain') != 'py':
            continue
        names: set[str] = set()
        for signode in objnode:
            if not isinstance(signode, addnodes.desc_signature):
                continue
            modname = signode.get('module')
            fullname = signode.get('fullname')
            refname = modname
            if env.config.viewcode_follow_imported_members:
                new_modname = events.emit_firstresult(
                    'viewcode-follow-imported', modname, fullname
                )
                if not new_modname:
                    new_modname = _get_full_modname(modname, fullname)
                modname = new_modname
            if not modname:
                continue
            fullname = signode.get('fullname')
            if not has_tag(modname, fullname, env.current_document.docname, refname):
                continue
            if fullname in names:
                # only one link per name, please
                continue
            names.add(fullname)
            pagename = posixpath.join(OUTPUT_DIRNAME, modname.replace('.', '/'))
            signode += viewcode_anchor(
                reftarget=pagename, refid=fullname, refdoc=env.current_document.docname
            )


def env_merge_info(
    app: Sphinx, env: BuildEnvironment, docnames: Set[str], other: BuildEnvironment
) -> None:
    if not hasattr(other, '_viewcode_modules'):
        return
    # create a _viewcode_modules dict on the main environment
    if not hasattr(env, '_viewcode_modules'):
        env._viewcode_modules = {}  # type: ignore[attr-defined]
    # now merge in the information from the subprocess
    for modname, entry in other._viewcode_modules.items():
        if modname not in env._viewcode_modules:  # type: ignore[attr-defined]
            env._viewcode_modules[modname] = entry  # type: ignore[attr-defined]
        else:
            if env._viewcode_modules[modname]:  # type: ignore[attr-defined]
                used = env._viewcode_modules[modname][2]  # type: ignore[attr-defined]
                for fullname, docname in entry[2].items():
                    if fullname not in used:
                        used[fullname] = docname


def env_purge_doc(app: Sphinx, env: BuildEnvironment, docname: str) -> None:
    modules = getattr(env, '_viewcode_modules', {})

    for modname, entry in list(modules.items()):
        if entry is False:
            continue

        _code, _tags, used, _refname = entry
        for fullname in list(used):
            if used[fullname] == docname:
                used.pop(fullname)

        if len(used) == 0:
            modules.pop(modname)


class ViewcodeAnchorTransform(SphinxPostTransform):
    """Convert or remove viewcode_anchor nodes depends on builder."""

    default_priority = 100

    def run(self, **kwargs: Any) -> None:
        if is_supported_builder(
            self.env._builder_cls, self.config.viewcode_enable_epub
        ):
            self.convert_viewcode_anchors()
        else:
            self.remove_viewcode_anchors()

    def convert_viewcode_anchors(self) -> None:
        for node in self.document.findall(viewcode_anchor):
            anchor = nodes.inline('', _('[source]'), classes=['viewcode-link'])
            refnode = make_refnode(
                self.env._app.builder,
                node['refdoc'],
                node['reftarget'],
                node['refid'],
                anchor,
            )
            node.replace_self(refnode)

    def remove_viewcode_anchors(self) -> None:
        for node in list(self.document.findall(viewcode_anchor)):
            node.parent.remove(node)


def get_module_filename(app: Sphinx, modname: str) -> _StrPath | None:
    """Get module filename for *modname*."""
    events = app.events
    source_info = events.emit_firstresult('viewcode-find-source', modname)

    r'^\s*((?::(?P<role>\S+):)?`(?P<name>~?[a-zA-Z0-9_.-]+)`|'
    r' (?P<name2>~?[a-zA-Z0-9_.-]+))\s*',
    re.VERBOSE,
)

def __init__(
    self,
    docstring: str | list[str],
    config: SphinxConfig | None = None,
    app: Sphinx | None = None,
    what: str = '',
    name: str = '',
    obj: Any = None,
    options: Any = None,
) -> None:
    self._app = app
    if config:
        self._config = config
    elif app:
        self._config = app.config
    else:
        from sphinx.ext.napoleon import Config

        self._config = Config()  # type: ignore[assignment]

    if not what:
        if inspect.isclass(obj):
            what = 'class'
        elif inspect.ismodule(obj):
            what = 'module'
        elif callable(obj):
            what = 'function'
        else:
            what = 'object'

    self._what = what
    self._name = name
    self._obj = obj
    self._opt = options
    if isinstance(docstring, str):
        lines = docstring.splitlines()
    else:
        lines = docstring
    self._lines = Deque(map(str.rstrip, lines))
    self._parsed_lines: list[str] = []
    self._is_in_section = False
    self._section_indent = 0
    if not hasattr(self, '_directive_sections'):
        self._directive_sections: list[str] = []
    if not hasattr(self, '_sections'):
        self._sections: dict[str, Callable[..., list[str]]] = {
            'args': self._parse_parameters_section,
            'arguments': self._parse_parameters_section,
            'attention': partial(self._parse_admonition, 'attention'),
            'attributes': self._parse_attributes_section,
            'caution': partial(self._parse_admonition, 'caution'),
            'danger': partial(self._parse_admonition, 'danger'),
            'error': partial(self._parse_admonition, 'error'),
            'example': self._parse_examples_section,
            'examples': self._parse_examples_section,
            'hint': partial(self._parse_admonition, 'hint'),
            'important': partial(self._parse_admonition, 'important'),
            'keyword args': self._parse_keyword_arguments_section,
            'keyword arguments': self._parse_keyword_arguments_section,
            'methods': self._parse_methods_section,
            'note': partial(self._parse_admonition, 'note'),
            'notes': self._parse_notes_section,
            'other parameters': self._parse_other_parameters_section,
            'parameters': self._parse_parameters_section,
            'receive': self._parse_receives_section,
            'receives': self._parse_receives_section,
            'return': self._parse_returns_section,
            'returns': self._parse_returns_section,
            'raise': self._parse_raises_section,
            'raises': self._parse_raises_section,
            'references': self._parse_references_section,
            'see also': self._parse_see_also_section,
            'tip': partial(self._parse_admonition, 'tip'),
            'todo': partial(self._parse_admonition, 'todo'),
            'warning': partial(self._parse_admonition, 'warning'),
            'warnings': partial(self._parse_admonition, 'warning'),
            'warn': self._parse_warns_section,
            'warns': self._parse_warns_section,
            'yield': self._parse_yields_section,
            'yields': self._parse_yields_section,
        }

    self._load_custom_sections()

    self._parse()












def _get_location(self) -> str | None:
    try:
        filepath = inspect.getfile(self._obj) if self._obj is not None else None
    except TypeError:
        filepath = None
    name = self._name

    if filepath is None and name is None:
        return None
    elif filepath is None:
        filepath = ''

    return f'{filepath}:docstring of {name}'

def lines(self) -> list[str]:
    """Return the parsed lines of the docstring in reStructuredText format.

    Returns
    -------
    list(str)
        The lines of the docstring in a list.

    """
    return self._parsed_lines

def _consume_indented_block(self, indent: int = 1) -> list[str]:
    lines = []
    line = self._lines.get(0)
    while not self._is_section_break() and (
        not line or self._is_indented(line, indent)
    ):
        lines.append(self._lines.next())
        line = self._lines.get(0)
    return lines

def _consume_contiguous(self) -> list[str]:
    lines = []
    while self._lines and self._lines.get(0) and not self._is_section_header():
        lines.append(self._lines.next())
    return lines

def _consume_empty(self) -> list[str]:
    lines = []
    line = self._lines.get(0)
    while self._lines and not line:
        lines.append(self._lines.next())
        line = self._lines.get(0)
    return lines

def _consume_field(
    self,
    parse_type: bool = True,
    prefer_type: bool = False,
) -> tuple[str, str, list[str]]:
    line = self._lines.next()

    before, _colon, after = self._partition_field_on_colon(line)
    _name, _type, _desc = before, '', after

    if parse_type:
        match = _google_typed_arg_regex.match(before)
        if match:
            _name = match.group(1).strip()
            _type = match.group(2)

    _name = self._escape_args_and_kwargs(_name)

    if prefer_type and not _type:
        _type, _name = _name, _type

    if _type and self._config.napoleon_preprocess_types:
        _type = _convert_type_spec(
            _type,
            translations=self._config.napoleon_type_aliases or {},
            debug_location=self._get_location(),
        )

    indent = self._get_indent(line) + 1
    _descs = [_desc, *self._dedent(self._consume_indented_block(indent))]
    _descs = self.__class__(_descs, self._config).lines()
    return _name, _type, _descs

def _consume_fields(
    self, parse_type: bool = True, prefer_type: bool = False, multiple: bool = False
) -> list[tuple[str, str, list[str]]]:
    self._consume_empty()
    fields: list[tuple[str, str, list[str]]] = []
    while not self._is_section_break():
        _name, _type, _desc = self._consume_field(parse_type, prefer_type)
        if multiple and _name:
            fields.extend((name.strip(), _type, _desc) for name in _name.split(','))
        elif _name or _type or _desc:
            fields.append((_name, _type, _desc))
    return fields

def _consume_inline_attribute(self) -> tuple[str, list[str]]:
    line = self._lines.next()
    _type, colon, _desc = self._partition_field_on_colon(line)
    if not colon or not _desc:
        _type, _desc = _desc, _type
        _desc += colon
    _descs = [_desc, *self._dedent(self._consume_to_end())]
    _descs = self.__class__(_descs, self._config).lines()
    return _type, _descs

def _consume_returns_section(
    self, preprocess_types: bool = False
) -> list[tuple[str, str, list[str]]]:
    lines = self._dedent(self._consume_to_next_section())
    if lines:
        before, colon, after = self._partition_field_on_colon(lines[0])
        _name, _type, _desc = '', '', lines

        if colon:
            if after:
                _desc = [after, *lines[1:]]
            else:
                _desc = lines[1:]

            _type = before

        if _type and preprocess_types and self._config.napoleon_preprocess_types:
            _type = _convert_type_spec(
                _type,
                translations=self._config.napoleon_type_aliases or {},
                debug_location=self._get_location(),
            )

        _desc = self.__class__(_desc, self._config).lines()
        return [(_name, _type, _desc)]
    else:
        return []

def _consume_usage_section(self) -> list[str]:
    lines = self._dedent(self._consume_to_next_section())
    return lines

def _consume_section_header(self) -> str:
    section = self._lines.next()
    stripped_section = section.strip(':')
    if stripped_section.lower() in self._sections:
        section = stripped_section
    return section

def _consume_to_end(self) -> list[str]:
    lines = []
    while self._lines:
        lines.append(self._lines.next())
    return lines

def _consume_to_next_section(self) -> list[str]:
    self._consume_empty()
    lines = []
    while not self._is_section_break():
        lines.append(self._lines.next())
    return lines + self._consume_empty()

def _dedent(self, lines: list[str], full: bool = False) -> list[str]:
    if full:
        return [line.lstrip() for line in lines]
    else:
        min_indent = self._get_min_indent(lines)
        return [line[min_indent:] for line in lines]

def _escape_args_and_kwargs(self, name: str) -> str:
    if name.endswith('_') and getattr(
        self._config, 'strip_signature_backslash', False
    ):
        name = name[:-1] + r'\_'

    if name[:2] == '**':
        return r'\*\*' + name[2:]
    elif name[:1] == '*':
        return r'\*' + name[1:]
    else:
        return name

def _fix_field_desc(self, desc: list[str]) -> list[str]:
    if self._is_list(desc):
        desc = ['', *desc]
    elif desc[0].endswith('::'):
        desc_block = desc[1:]
        indent = self._get_indent(desc[0])
        block_indent = self._get_initial_indent(desc_block)
        if block_indent > indent:
            desc = ['', *desc]
        else:
            desc = ['', desc[0], *self._indent(desc_block, 4)]
    return desc

def _format_admonition(self, admonition: str, lines: list[str]) -> list[str]:
    lines = self._strip_empty(lines)
    if len(lines) == 1:
        return [f'.. {admonition}:: {lines[0].strip()}', '']
    elif lines:
        lines = self._indent(self._dedent(lines), 3)
        return [f'.. {admonition}::', '', *lines, '']
    else:
        return [f'.. {admonition}::', '']

def _format_block(
    self,
    prefix: str,
    lines: list[str],
    padding: str | None = None,
) -> list[str]:
    if lines:
        if padding is None:
            padding = ' ' * len(prefix)
        result_lines = []
        for i, line in enumerate(lines):
            if i == 0:
                result_lines.append((prefix + line).rstrip())
            elif line:
                result_lines.append(padding + line)
            else:
                result_lines.append('')
        return result_lines

    else:
        return [prefix]

def _format_docutils_params(
    self,
    fields: list[tuple[str, str, list[str]]],
    field_role: str = 'param',
    type_role: str = 'type',
) -> list[str]:
    lines = []
    for _name, _type, _desc in fields:
        _desc = self._strip_empty(_desc)
        if any(_desc):
            _desc = self._fix_field_desc(_desc)
            field = f':{field_role} {_name}: '
            lines.extend(self._format_block(field, _desc))
        else:
            lines.append(f':{field_role} {_name}:')

        if _type:
            lines.append(f':{type_role} {_name}: {_type}')
    return [*lines, '']

def _format_field(self, _name: str, _type: str, _desc: list[str]) -> list[str]:
    _desc = self._strip_empty(_desc)
    has_desc = any(_desc)
    separator = ' -- ' if has_desc else ''
    if _name:
        if _type:
            if '`' in _type:
                field = f'**{_name}** ({_type}){separator}'
            else:
                field = f'**{_name}** (*{_type}*){separator}'
        else:
            field = f'**{_name}**{separator}'
    elif _type:
        if '`' in _type:
            field = f'{_type}{separator}'
        else:
            field = f'*{_type}*{separator}'
    else:
        field = ''

    if has_desc:
        _desc = self._fix_field_desc(_desc)
        if _desc[0]:
            return [field + _desc[0], *_desc[1:]]
        else:
            return [field, *_desc]
    else:
        return [field]

def _format_fields(
    self,
    field_type: str,
    fields: list[tuple[str, str, list[str]]],
) -> list[str]:
    field_type = f':{field_type.strip()}:'
    padding = ' ' * len(field_type)
    multi = len(fields) > 1
    lines: list[str] = []
    for _name, _type, _desc in fields:
        field = self._format_field(_name, _type, _desc)
        if multi:
            if lines:
                lines.extend(self._format_block(padding + ' * ', field))
            else:
                lines.extend(self._format_block(field_type + ' * ', field))
        else:
            lines.extend(self._format_block(field_type + ' ', field))
    if lines and lines[-1]:
        lines.append('')
    return lines

def _get_current_indent(self, peek_ahead: int = 0) -> int:
    line = self._lines.get(peek_ahead)
    while line is not self._lines.sentinel:
        if line:
            return self._get_indent(line)
        peek_ahead += 1
        line = self._lines.get(peek_ahead)
    return 0

def _get_indent(self, line: str) -> int:
    for i, s in enumerate(line):
        if not s.isspace():
            return i
    return len(line)

def _get_initial_indent(self, lines: list[str]) -> int:
    for line in lines:
        if line:
            return self._get_indent(line)
    return 0

def _get_min_indent(self, lines: list[str]) -> int:
    min_indent = None
    for line in lines:
        if line:
            indent = self._get_indent(line)
            if min_indent is None or indent < min_indent:
                min_indent = indent
    return min_indent or 0

def _indent(self, lines: list[str], n: int = 4) -> list[str]:
    return [(' ' * n) + line for line in lines]

def _is_indented(self, line: str, indent: int = 1) -> bool:
    for i, s in enumerate(line):
        if i >= indent:
            return True
        elif not s.isspace():
            return False
    return False

def _is_list(self, lines: list[str]) -> bool:
    if not lines:
        return False
    if _bullet_list_regex.match(lines[0]):
        return True
    if _enumerated_list_regex.match(lines[0]):
        return True
    if len(lines) < 2 or lines[0].endswith('::'):
        return False
    indent = self._get_indent(lines[0])
    next_indent = indent
    for line in lines[1:]:
        if line:
            next_indent = self._get_indent(line)
            break
    return next_indent > indent

def _is_section_header(self) -> bool:
    section = self._lines.get(0).lower()
    match = _google_section_regex.match(section)
    if match and section.strip(':') in self._sections:
        header_indent = self._get_indent(section)
        section_indent = self._get_current_indent(peek_ahead=1)
        return section_indent > header_indent
    elif self._directive_sections:
        if _directive_regex.match(section):
            for directive_section in self._directive_sections:
                if section.startswith(directive_section):
                    return True
    return False

def _is_section_break(self) -> bool:
    line = self._lines.get(0)
    return (
        not self._lines
        or self._is_section_header()
        or (
            self._is_in_section
            and line
            and not self._is_indented(line, self._section_indent)
        )
    )

def _load_custom_sections(self) -> None:
    if self._config.napoleon_custom_sections is not None:
        for entry in self._config.napoleon_custom_sections:
            if isinstance(entry, str):
                # if entry is just a label, add to sections list,
                # using generic section logic.
                self._sections[entry.lower()] = self._parse_custom_generic_section
            else:
                # otherwise, assume entry is container;
                if entry[1] == 'params_style':
                    self._sections[entry[0].lower()] = (
                        self._parse_custom_params_style_section
                    )
                elif entry[1] == 'returns_style':
                    self._sections[entry[0].lower()] = (
                        self._parse_custom_returns_style_section
                    )
                else:
                    # [0] is new section, [1] is the section to alias.
                    # in the case of key mismatch, just handle as generic section.
                    self._sections[entry[0].lower()] = self._sections.get(
                        entry[1].lower(), self._parse_custom_generic_section
                    )

def _parse(self) -> None:
    self._parsed_lines = self._consume_empty()

    if self._name and self._what in {'attribute', 'data', 'property'}:
        res: list[str] = []
        with contextlib.suppress(StopIteration):
            res = self._parse_attribute_docstring()

        self._parsed_lines.extend(res)
        return

    while self._lines:
        if self._is_section_header():
            try:
                section = self._consume_section_header()
                self._is_in_section = True
                self._section_indent = self._get_current_indent()
                if _directive_regex.match(section):
                    lines = [section, *self._consume_to_next_section()]
                else:
                    lines = self._sections[section.lower()](section)
            finally:
                self._is_in_section = False
                self._section_indent = 0
        else:
            if not self._parsed_lines:
                lines = self._consume_contiguous() + self._consume_empty()
            else:
                lines = self._consume_to_next_section()
        self._parsed_lines.extend(lines)

def _parse_admonition(self, admonition: str, section: str) -> list[str]:
    # type (str, str) -> List[str]
    lines = self._consume_to_next_section()
    return self._format_admonition(admonition, lines)

def _parse_attribute_docstring(self) -> list[str]:
    _type, _desc = self._consume_inline_attribute()
    lines = self._format_field('', '', _desc)
    if _type:
        lines.extend(['', f':type: {_type}'])
    return lines

def _parse_attributes_section(self, section: str) -> list[str]:
    lines = []
    for _name, _type, _desc in self._consume_fields():
        if not _type:
            _type = self._lookup_annotation(_name)
        if self._config.napoleon_use_ivar:
            field = f':ivar {_name}: '
            lines.extend(self._format_block(field, _desc))
            if _type:
                lines.append(f':vartype {_name}: {_type}')
        else:
            lines.append('.. attribute:: ' + _name)
            if self._opt:
                if 'no-index' in self._opt or 'noindex' in self._opt:
                    lines.append('   :no-index:')
            lines.append('')

            fields = self._format_field('', '', _desc)
            lines.extend(self._indent(fields, 3))
            if _type:
                lines.append('')
                lines.extend(self._indent([f':type: {_type}'], 3))
            lines.append('')
    if self._config.napoleon_use_ivar:
        lines.append('')
    return lines

def _parse_examples_section(self, section: str) -> list[str]:
    labels = {
        'example': _('Example'),
        'examples': _('Examples'),
    }
    use_admonition = self._config.napoleon_use_admonition_for_examples
    label = labels.get(section.lower(), section)
    return self._parse_generic_section(label, use_admonition)

def _parse_custom_generic_section(self, section: str) -> list[str]:
    # for now, no admonition for simple custom sections
    return self._parse_generic_section(section, False)

def _parse_custom_params_style_section(self, section: str) -> list[str]:
    return self._format_fields(section, self._consume_fields())

def _parse_custom_returns_style_section(self, section: str) -> list[str]:
    fields = self._consume_returns_section(preprocess_types=True)
    return self._format_fields(section, fields)

def _parse_usage_section(self, section: str) -> list[str]:
    header = ['.. rubric:: Usage:', '']
    block = ['.. code-block:: python', '']
    lines = self._consume_usage_section()
    lines = self._indent(lines, 3)
    return header + block + lines + ['']

def _parse_generic_section(self, section: str, use_admonition: bool) -> list[str]:
    lines = self._strip_empty(self._consume_to_next_section())
    lines = self._dedent(lines)
    if use_admonition:
        header = f'.. admonition:: {section}'
        lines = self._indent(lines, 3)
    else:
        header = f'.. rubric:: {section}'
    if lines:
        return [header, '', *lines, '']
    else:
        return [header, '']

def _parse_keyword_arguments_section(self, section: str) -> list[str]:
    fields = self._consume_fields()
    if self._config.napoleon_use_keyword:
        return self._format_docutils_params(
            fields, field_role='keyword', type_role='kwtype'
        )
    else:
        return self._format_fields(_('Keyword Arguments'), fields)

def _parse_methods_section(self, section: str) -> list[str]:
    lines: list[str] = []
    for _name, _type, _desc in self._consume_fields(parse_type=False):
        lines.append(f'.. method:: {_name}')
        if self._opt:
            if 'no-index' in self._opt or 'noindex' in self._opt:
                lines.append('   :no-index:')
        if _desc:
            lines.extend(['', *self._indent(_desc, 3)])
        lines.append('')
    return lines

def _parse_notes_section(self, section: str) -> list[str]:
    use_admonition = self._config.napoleon_use_admonition_for_notes
    return self._parse_generic_section(_('Notes'), use_admonition)

def _parse_other_parameters_section(self, section: str) -> list[str]:
    if self._config.napoleon_use_param:
        # Allow to declare multiple parameters at once (ex: x, y: int)

            fields = self._consume_fields(multiple=True)
            return self._format_docutils_params(fields)
        else:
            fields = self._consume_fields()
            return self._format_fields(_('Other Parameters'), fields)

    def _parse_parameters_section(self, section: str) -> list[str]:
        if self._config.napoleon_use_param:
            # Allow to declare multiple parameters at once (ex: x, y: int)
            fields = self._consume_fields(multiple=True)
            return self._format_docutils_params(fields)
        else:
            fields = self._consume_fields()
            return self._format_fields(_('Parameters'), fields)

    def _parse_raises_section(self, section: str) -> list[str]:
        fields = self._consume_fields(parse_type=False, prefer_type=True)
        lines: list[str] = []
        for _name, _type, _desc in fields:
            m = self._name_rgx.match(_type)
            if m and m.group('name'):
                _type = m.group('name')
            elif _xref_regex.match(_type):
                pos = _type.find('`')
                _type = _type[pos + 1 : -1]
            _type = ' ' + _type if _type else ''
            _desc = self._strip_empty(_desc)
            _descs = ' ' + '\n    '.join(_desc) if any(_desc) else ''
            lines.append(f':raises{_type}:{_descs}')
        if lines:
            lines.append('')
        return lines

    def _parse_receives_section(self, section: str) -> list[str]:
        if self._config.napoleon_use_param:
            # Allow to declare multiple parameters at once (ex: x, y: int)
            fields = self._consume_fields(multiple=True)
            return self._format_docutils_params(fields)
        else:
            fields = self._consume_fields()
            return self._format_fields(_('Receives'), fields)

    def _parse_references_section(self, section: str) -> list[str]:
        use_admonition = self._config.napoleon_use_admonition_for_references
        return self._parse_generic_section(_('References'), use_admonition)

    def _parse_returns_section(self, section: str) -> list[str]:
        fields = self._consume_returns_section()
        multi = len(fields) > 1
        use_rtype = False if multi else self._config.napoleon_use_rtype
        lines: list[str] = []

        for _name, _type, _desc in fields:
            if use_rtype:
                field = self._format_field(_name, '', _desc)
            else:
                field = self._format_field(_name, _type, _desc)

            if multi:
                if lines:
                    lines.extend(self._format_block('          * ', field))
                else:
                    lines.extend(self._format_block(':returns: * ', field))
            else:
                if any(field):  # only add :returns: if there's something to say
                    lines.extend(self._format_block(':returns: ', field))
                if _type and use_rtype:
                    lines.extend([f':rtype: {_type}', ''])
        if lines and lines[-1]:
            lines.append('')
        return lines

    def _parse_see_also_section(self, section: str) -> list[str]:
        return self._parse_admonition('seealso', section)

    def _parse_warns_section(self, section: str) -> list[str]:
        return self._format_fields(_('Warns'), self._consume_fields())

    def _parse_yields_section(self, section: str) -> list[str]:
        fields = self._consume_returns_section(preprocess_types=True)
        return self._format_fields(_('Yields'), fields)

    def _partition_field_on_colon(self, line: str) -> tuple[str, str, str]:
        before_colon = []
        after_colon = []
        colon = ''
        found_colon = False
        for i, source in enumerate(_xref_or_code_regex.split(line)):
            if found_colon:
                after_colon.append(source)
            else:
                m = _single_colon_regex.search(source)
                if (i % 2) == 0 and m:
                    found_colon = True
                    colon = source[m.start() : m.end()]
                    before_colon.append(source[: m.start()])
                    after_colon.append(source[m.end() :])
                else:
                    before_colon.append(source)

        return ''.join(before_colon).strip(), colon, ''.join(after_colon).strip()

    def _strip_empty(self, lines: list[str]) -> list[str]:
        if lines:
            start = -1
            for i, line in enumerate(lines):
                if line:
                    start = i
                    break
            if start == -1:
                lines = []
            end = -1
            for i in reversed(range(len(lines))):
                line = lines[i]
                if line:
                    end = i
                    break
            if start > 0 or end + 1 < len(lines):
                lines = lines[start : end + 1]
        return lines

    def _lookup_annotation(self, _name: str) -> str:
        if self._config.napoleon_attr_annotations:
            if self._what in {'module', 'class', 'exception'} and self._obj:
                # cache the class annotations
                if not hasattr(self, '_annotations'):
                    localns = getattr(self._config, 'autodoc_type_aliases', {})
                    localns.update(
                        getattr(
                            self._config,
                            'napoleon_type_aliases',
                            {},
                        )
                        or {}
                    )
                    self._annotations = get_type_hints(self._obj, None, localns)
                if _name in self._annotations:
                    short_literals = getattr(
                        self._config, 'python_display_short_literal_types', False
                    )
                    return stringify_annotation(
                        self._annotations[_name],
                        mode='fully-qualified-except-typing',
                        short_literals=short_literals,
                    )
        # No annotation found
        return ''


class NumpyDocstring(GoogleDocstring):
    """Convert NumPy style docstrings to reStructuredText.

    Parameters
    ----------
    docstring : :obj:`str` or :obj:`list` of :obj:`str`
        The docstring to parse, given either as a string or split into
        individual lines.
    config: :obj:`sphinx.ext.napoleon.Config` or :obj:`sphinx.config.Config`
        The configuration settings to use. If not given, defaults to the
        config object on `app`; or if `app` is not given defaults to the
        a new :class:`sphinx.ext.napoleon.Config` object.


    Other Parameters
    ----------------
    app : :class:`sphinx.application.Sphinx`, optional
        Application object representing the Sphinx process.
    what : :obj:`str`, optional
        A string specifying the type of the object to which the docstring
        belongs. Valid values: "module", "class", "exception", "function",
        "method", "attribute".
    name : :obj:`str`, optional
        The fully qualified name of the object.
    obj : module, class, exception, function, method, or attribute
        The object to which the docstring belongs.
    options : :class:`sphinx.ext.autodoc.Options`, optional
        The options given to the directive: an object with attributes
        inherited_members, undoc_members, show_inheritance and no_index that
        are True if the flag option of same name was given to the auto
        directive.


    Example
    -------
    >>> from sphinx.ext.napoleon import Config
    >>> config = Config(napoleon_use_param=True, napoleon_use_rtype=True)
    >>> docstring = '''One line summary.
    ...
    ... Extended description.
    ...
    ... Parameters
    ... ----------
    ... arg1 : int
    ...     Description of `arg1`
    ... arg2 : str
    ...     Description of `arg2`
    ... Returns
    ... -------
    ... str
    ...     Description of return value.
    ... '''
    >>> print(NumpyDocstring(docstring, config))
    One line summary.
    <BLANKLINE>
    Extended description.
    <BLANKLINE>
    :param arg1: Description of `arg1`
    :type arg1: int
    :param arg2: Description of `arg2`
    :type arg2: str
    <BLANKLINE>
    :returns: Description of return value.
    :rtype: str
    <BLANKLINE>

    Methods
    -------
    __str__()
        Return the parsed docstring in reStructuredText format.

        Returns
        -------
        str
            UTF-8 encoded version of the docstring.

    __unicode__()
        Return the parsed docstring in reStructuredText format.

        Returns
        -------
        unicode
            Unicode version of the docstring.

    lines()
        Return the parsed lines of the docstring in reStructuredText format.

        Returns
        -------
        list(str)
            The lines of the docstring in a list.

    """

    def __init__(
        self,
        docstring: str | list[str],
        config: SphinxConfig | None = None,
        app: Sphinx | None = None,
        what: str = '',
        name: str = '',
        obj: Any = None,
        options: Any = None,
    ) -> None:
        self._directive_sections = ['.. index::']
        super().__init__(docstring, config, app, what, name, obj, options)

    def _escape_args_and_kwargs(self, name: str) -> str:
        func = super()._escape_args_and_kwargs

        if ', ' in name:
            return ', '.join(map(func, name.split(', ')))
        else:
            return func(name)

    def _consume_field(
        self, parse_type: bool = True, prefer_type: bool = False
    ) -> tuple[str, str, list[str]]:
        line = self._lines.next()
        if parse_type:
            _name, _, _type = self._partition_field_on_colon(line)
        else:
            _name, _type = line, ''
        _name, _type = _name.strip(), _type.strip()
        _name = self._escape_args_and_kwargs(_name)

        if parse_type and not _type:
            _type = self._lookup_annotation(_name)

        if prefer_type and not _type:
            _type, _name = _name, _type

        if self._config.napoleon_preprocess_types:
            _type = _convert_type_spec(
                _type,
                translations=self._config.napoleon_type_aliases or {},
                debug_location=self._get_location(),
            )

        indent = self._get_indent(line) + 1
        _desc = self._dedent(self._consume_indented_block(indent))
        _desc = self.__class__(_desc, self._config).lines()
        return _name, _type, _desc

    def _consume_returns_section(
        self, preprocess_types: bool = False
    ) -> list[tuple[str, str, list[str]]]:
        return self._consume_fields(prefer_type=True)

    def _consume_section_header(self) -> str:
        section = self._lines.next()
        if not _directive_regex.match(section):
            # Consume the header underline
            self._lines.next()
        return section

    def _is_section_break(self) -> bool:
        line1, line2 = self._lines.get(0), self._lines.get(1)
        return (
            not self._lines
            or self._is_section_header()
            or (not line1 and not line2)
            or (
                self._is_in_section
                and line1
                and not self._is_indented(line1, self._section_indent)
            )
        )

    def _is_section_header(self) -> bool:
        section, underline = self._lines.get(0), self._lines.get(1)

    section = section.lower()
    if section in self._sections and isinstance(underline, str):
        return bool(_numpy_section_regex.match(underline))
    elif self._directive_sections:
        if _directive_regex.match(section):
            for directive_section in self._directive_sections:
                if section.startswith(directive_section):
                    return True
    return False

def _parse_see_also_section(self, section: str) -> list[str]:
    lines = self._consume_to_next_section()
    try:
        return self._parse_numpydoc_see_also_section(lines)
    except ValueError:
        return self._format_admonition('seealso', lines)

def _parse_numpydoc_see_also_section(self, content: list[str]) -> list[str]:
    """See Also
    --------
    func_name : Descriptive text
        continued text
    another_func_name : Descriptive text
    func_name1, func_name2, :meth:`func_name`, func_name3

    Licence
    -------

    Derived from the NumpyDoc implementation of ``_parse_see_also``,
    which was under the following licence:

        Copyright (C) 2008 Stefan van der Walt <stefan@mentat.za.net>,
                           Pauli Virtanen <pav@iki.fi>

        Redistribution and use in source and binary forms, with or without
        modification, are permitted provided that the following conditions are
        met:

         1. Redistributions of source code must retain the above copyright
            notice, this list of conditions and the following disclaimer.
         2. Redistributions in binary form must reproduce the above copyright
            notice, this list of conditions and the following disclaimer in
            the documentation and/or other materials provided with the
            distribution.

        THIS SOFTWARE IS PROVIDED BY THE AUTHOR "AS IS" AND ANY EXPRESS OR
        IMPLIED WARRANTIES, INCLUDING, BUT NOT LIMITED TO, THE IMPLIED
        WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A PARTICULAR PURPOSE ARE
        DISCLAIMED. IN NO EVENT SHALL THE AUTHOR BE LIABLE FOR ANY DIRECT,
        INDIRECT, INCIDENTAL, SPECIAL, EXEMPLARY, OR CONSEQUENTIAL DAMAGES
        (INCLUDING, BUT NOT LIMITED TO, PROCUREMENT OF SUBSTITUTE GOODS OR
        SERVICES; LOSS OF USE, DATA, OR PROFITS; OR BUSINESS INTERRUPTION)
        HOWEVER CAUSED AND ON ANY THEORY OF LIABILITY, WHETHER IN CONTRACT,
        STRICT LIABILITY, OR TORT (INCLUDING NEGLIGENCE OR OTHERWISE) ARISING
        IN ANY WAY OUT OF THE USE OF THIS SOFTWARE, EVEN IF ADVISED OF THE
        POSSIBILITY OF SUCH DAMAGE.
    """
    items: list[tuple[str, list[str], str | None]] = []

    def parse_item_name(text: str) -> tuple[str, str | None]:
        """Match ':role:`name`' or 'name'"""
        m = self._name_rgx.match(text)
        if m:
            g = m.groups()
            if g[1] is None:
                return g[3], None
            else:
                return g[2], g[1]
        msg = f'{text} is not a item name'
        raise ValueError(msg)

    def push_item(name: str | None, rest: list[str]) -> None:
        if not name:
            return
        name, role = parse_item_name(name)
        items.append((name, rest.copy(), role))
        rest.clear()

    def translate(
        func: str,
        description: list[str],
        role: str | None,
    ) -> tuple[str, list[str], str | None]:
        translations = self._config.napoleon_type_aliases
        if role is not None or not translations:
            return func, description, role

        translated = translations.get(func, func)
        match = self._name_rgx.match(translated)
        if not match:
            return translated, description, role

        groups = match.groupdict()
        role = groups['role']
        new_func = groups['name'] or groups['name2']

        return new_func, description, role

    current_func = None
    rest: list[str] = []

    for line in content:
        if not line.strip():
            continue

        m = self._name_rgx.match(line)
        if m and line[m.end() :].strip().startswith(':'):
            push_item(current_func, rest)
            current_func, line = line[: m.end()], line[m.end() :]
            rest = [line.partition(':')[-1].strip()]
            if not rest[0]:
                rest = []
        elif not line.startswith(' '):
            push_item(current_func, rest)
            current_func = None
            if ',' in line:
                for func in line.split(','):
                    if func.strip():
                        push_item(func, [])
            elif line.strip():
                current_func = line
        elif current_func is not None:
            rest.append(line.strip())
    push_item(current_func, rest)

    if not items:
        return []

    # apply type aliases
    items = list(starmap(translate, items))

    lines: list[str] = []
    last_had_desc = True
    for name, desc, role in items:
        if role:
            link = f':{role}:`{name}`'
        else:
            link = f':py:obj:`{name}`'
        if desc or last_had_desc:
            lines += ['']
            lines += [link]
        else:
            lines[-1] += f', {link}'
        if desc:
            lines += self._indent([' '.join(desc)])
            last_had_desc = True
        else:
            last_had_desc = False
    lines += ['']

    return self._format_admonition('seealso', lines)

"""Utilities parsing and analyzing Python code."""

from __future__ import annotations

import tokenize
from importlib import import_module
from typing import TYPE_CHECKING

from sphinx.errors import PycodeError
from sphinx.pycode.parser import Parser
from sphinx.util._pathlib import _StrPath

if TYPE_CHECKING:
    import os
    from inspect import Signature
    from typing import Any, Literal


class ModuleAnalyzer:
    annotations: dict[tuple[str, str], str]
    attr_docs: dict[tuple[str, str], list[str]]
    finals: list[str]
    overloads: dict[str, list[Signature]]
    tagorder: dict[str, int]
    tags: dict[str, tuple[str, int, int]]

    # cache for analyzer objects -- caches both by module and file name
    cache: dict[tuple[Literal['file', 'module'], str | _StrPath], Any] = {}

    @staticmethod
    def get_module_source(modname: str) -> tuple[_StrPath | None, str | None]:
        """Try to find the source code for a module.

        Returns ('filename', 'source'). One of it can be None if
        no filename or source found
        """
        try:
            mod = import_module(modname)
        except Exception as err:
            raise PycodeError('error importing %r' % modname, err) from err
        loader = getattr(mod, '__loader__', None)
        filename: str | None = getattr(mod, '__file__', None)
        if loader and getattr(loader, 'get_source', None):
            # prefer Native loader, as it respects #coding directive
            try:
                source = loader.get_source(modname)
                if source:
                    mod_path = None if filename is None else _StrPath(filename)
                    # no exception and not None - it must be module source
                    return mod_path, source
            except ImportError:
                pass  # Try other "source-mining" methods
        if filename is None and loader and getattr(loader, 'get_filename', None):
            # have loader, but no filename
            try:
                filename = loader.get_filename(modname)
            except ImportError as err:
                raise PycodeError(
                    'error getting filename for %r' % modname, err
                ) from err
        if filename is None:
            # all methods for getting filename failed, so raise...
            raise PycodeError('no source found for module %r' % modname)
        mod_path = _StrPath(filename).resolve()
        if mod_path.suffix in {'.pyo', '.pyc'}:
            mod_path_pyw = mod_path.with_suffix('.pyw')
            if not mod_path.is_file() and mod_path_pyw.is_file():
                mod_path = mod_path_pyw
            else:
                mod_path = mod_path.with_suffix('.py')
        elif mod_path.suffix not in {'.py', '.pyw'}:
            msg = f'source is not a .py file: {mod_path!r}'
            raise PycodeError(msg)

        if not mod_path.is_file():
            msg = f'source file is not present: {mod_path!r}'
            raise PycodeError(msg)
        return mod_path, None

    @classmethod
    def for_string(
        cls: type[ModuleAnalyzer],
        string: str,
        modname: str,
        srcname: str | os.PathLike[str] = '<string>',
    ) -> ModuleAnalyzer:
        return cls(string, modname, srcname)

    @classmethod
    def for_file(
        cls: type[ModuleAnalyzer], filename: str | os.PathLike[str], modname: str
    ) -> ModuleAnalyzer:
        filename = _StrPath(filename)
        if ('file', filename) in cls.cache:
            return cls.cache['file', filename]
        try:
            with tokenize.open(filename) as f:
                string = f.read()
            obj = cls(string, modname, filename)
            cls.cache['file', filename] = obj
        except Exception as err:
            raise PycodeError('error opening %r' % filename, err) from err
        return obj

    @classmethod
    def for_module(cls: type[ModuleAnalyzer], modname: str) -> ModuleAnalyzer:
        if ('module', modname) in cls.cache:
            entry = cls.cache['module', modname]
            if isinstance(entry, PycodeError):
                raise entry
            return entry

        try:
            filename, source = cls.get_module_source(modname)
            if source is not None:
                obj = cls.for_string(source, modname, filename or '<string>')
            elif filename is not None:
                obj = cls.for_file(filename, modname)
        except PycodeError as err:
            cls.cache['module', modname] = err
            raise
        cls.cache['module', modname] = obj
        return obj

    def __init__(
        self, source: str, modname: str, srcname: str | os.PathLike[str]
    ) -> None:
        self.modname = modname  # name of the module
        self.srcname = str(srcname)  # name of the source file

        # cache the source code as well
        self.code = source

        self._analyzed = False

    def analyze(self) -> None:
        """Analyze the source code."""
        if self._analyzed:
            return

        try:
            parser = Parser(self.code)
            parser.parse()

            self.attr_docs = {}
            for scope, comment in parser.comments.items():
                if comment:
                    self.attr_docs[scope] = [*comment.splitlines(), '']
                else:
                    self.attr_docs[scope] = ['']

            self.annotations = parser.annotations
            self.finals = parser.finals
            self.overloads = parser.overloads
            self.tags = parser.definitions
            self.tagorder = parser.deforders
            self._analyzed = True
        except Exception as exc:
            msg = f'parsing {self.srcname!r} failed: {exc!r}'
            raise PycodeError(msg) from exc

    def find_attr_docs(self) -> dict[tuple[str, str], list[str]]:
        """Find class and module-level attributes and their documentation."""
        self.analyze()
        return self.attr_docs

    def find_tags(self) -> dict[str, tuple[str, int, int]]:
        """Find class, function and method definitions and their location."""
        self.analyze()
        return self.tags

"""Helpers for AST (Abstract Syntax Tree)."""

from __future__ import annotations

import ast
from typing import TYPE_CHECKING, overload

if TYPE_CHECKING:
    from typing import NoReturn

OPERATORS: dict[type[ast.AST], str] = {
    ast.Add: '+',
    ast.And: 'and',
    ast.BitAnd: '&',
    ast.BitOr: '|',
    ast.BitXor: '^',
    ast.Div: '/',
    ast.FloorDiv: '//',
    ast.Invert: '~',
    ast.LShift: '<<',
    ast.MatMult: '@',
    ast.Mult: '*',
    ast.Mod: '%',
    ast.Not: 'not',
    ast.Pow: '**',
    ast.Or: 'or',
    ast.RShift: '>>',
    ast.Sub: '-',
    ast.UAdd: '+',
    ast.USub: '-',
}


@overload
def unparse(node: None, code: str = '') -> None: ...


@overload
def unparse(node: ast.AST, code: str = '') -> str: ...


def unparse(node: ast.AST | None, code: str = '') -> str | None:
    """Unparse an AST to string."""
    if node is None:
        return None
    elif isinstance(node, str):
        return node
    return _UnparseVisitor(code).visit(node)


# a greatly cut-down version of `ast._Unparser`
class _UnparseVisitor(ast.NodeVisitor):
    def __init__(self, code: str = '') -> None:
        self.code = code

    def _visit_op(self, node: ast.AST) -> str:
        return OPERATORS[node.__class__]

    for _op in OPERATORS:
        locals()[f'visit_{_op.__name__}'] = _visit_op

    def visit_arg(self, node: ast.arg) -> str:
        if node.annotation:
            return f'{node.arg}: {self.visit(node.annotation)}'
        else:
            return node.arg

    def _visit_arg_with_default(self, arg: ast.arg, default: ast.AST | None) -> str:
        """Unparse a single argument to a string."""
        name = self.visit(arg)
        if default:
            if arg.annotation:
                name += ' = %s' % self.visit(default)
            else:
                name += '=%s' % self.visit(default)
        return name

    def visit_arguments(self, node: ast.arguments) -> str:
        defaults: list[ast.expr | None] = list(node.defaults)
        positionals = len(node.args)
        posonlyargs = len(node.posonlyargs)
        positionals += posonlyargs
        for _ in range(len(defaults), positionals):
            defaults.insert(0, None)

        kw_defaults: list[ast.expr | None] = list(node.kw_defaults)
        for _ in range(len(kw_defaults), len(node.kwonlyargs)):
            kw_defaults.insert(0, None)

        args: list[str] = [
            self._visit_arg_with_default(arg, defaults[i])
            for i, arg in enumerate(node.posonlyargs)
        ]

        if node.posonlyargs:
            args.append('/')

        for i, arg in enumerate(node.args):
            args.append(self._visit_arg_with_default(arg, defaults[i + posonlyargs]))

        if node.vararg:
            args.append('*' + self.visit(node.vararg))

        if node.kwonlyargs and not node.vararg:
            args.append('*')
        for i, arg in enumerate(node.kwonlyargs):
            args.append(self._visit_arg_with_default(arg, kw_defaults[i]))

        if node.kwarg:
            args.append('**' + self.visit(node.kwarg))

        return ', '.join(args)

    def visit_Attribute(self, node: ast.Attribute) -> str:
        return f'{self.visit(node.value)}.{node.attr}'

    def visit_BinOp(self, node: ast.BinOp) -> str:
        # Special case ``**`` to not have surrounding spaces.
        if isinstance(node.op, ast.Pow):
            return ''.join(map(self.visit, (node.left, node.op, node.right)))
        return ' '.join(map(self.visit, (node.left, node.op, node.right)))

    def visit_BoolOp(self, node: ast.BoolOp) -> str:
        op = ' %s ' % self.visit(node.op)
        return op.join(self.visit(e) for e in node.values)

    def visit_Call(self, node: ast.Call) -> str:
        args = ', '.join(
            [self.visit(e) for e in node.args]
            + [f'{k.arg}={self.visit(k.value)}' for k in node.keywords],
        )
        return f'{self.visit(node.func)}({args})'

    def visit_Constant(self, node: ast.Constant) -> str:
        if node.value is Ellipsis:
            return '...'
        elif isinstance(node.value, (int, float, complex)):
            if self.code:
                return ast.get_source_segment(self.code, node) or repr(node.value)
            else:
                return repr(node.value)
        else:
            return repr(node.value)

    def visit_Dict(self, node: ast.Dict) -> str:
        keys = (self.visit(k) for k in node.keys if k is not None)
        values = (self.visit(v) for v in node.values)
        items = (k + ': ' + v for k, v in zip(keys, values, strict=True))
        return '{' + ', '.join(items) + '}'

    def visit_Lambda(self, node: ast.Lambda) -> str:
        return 'lambda %s: ...' % self.visit(node.args)

    def visit_List(self, node: ast.List) -> str:
        return '[' + ', '.join(self.visit(e) for e in node.elts) + ']'

    def visit_Name(self, node: ast.Name) -> str:
        return node.id

    def visit_Set(self, node: ast.Set) -> str:
        return '{' + ', '.join(self.visit(e) for e in node.elts) + '}'

    def visit_Slice(self, node: ast.Slice) -> str:
        if not node.lower and not node.upper and not node.step:
            # Empty slice with default values -> [:]
            return ':'

        start = self.visit(node.lower) if node.lower else ''
        stop = self.visit(node.upper) if node.upper else ''
        if not node.step:
            # Default step size -> [start:stop]
            return f'{start}:{stop}'

        step = self.visit(node.step) if node.step else ''
        return f'{start}:{stop}:{step}'

    def visit_Subscript(self, node: ast.Subscript) -> str:
        def is_simple_tuple(value: ast.expr) -> bool:
            return (
                isinstance(value, ast.Tuple)
                and bool(value.elts)
                and not any(isinstance(elt, ast.Starred) for elt in value.elts)
            )

        if is_simple_tuple(node.slice):
            elts = ', '.join(self.visit(e) for e in node.slice.elts)  # type: ignore[attr-defined]
            return f'{self.visit(node.value)}[{elts}]'
        return f'{self.visit(node.value)}[{self.visit(node.slice)}]'

    def visit_UnaryOp(self, node: ast.UnaryOp) -> str:
        # UnaryOp is one of {UAdd, USub, Invert, Not}, which refer to ``+x``,
        # ``-x``, ``~x``, and ``not x``. Only Not needs a space.
        if isinstance(node.op, ast.Not):
            return f'{self.visit(node.op)} {self.visit(node.operand)}'
        return f'{self.visit(node.op)}{self.visit(node.operand)}'

    def visit_Tuple(self, node: ast.Tuple) -> str:
        if len(node.elts) == 0:
            return '()'
        elif len(node.elts) == 1:
            return '(%s,)' % self.visit(node.elts[0])
        else:
            return '(' + ', '.join(self.visit(e) for e in node.elts) + ')'

    def visit_Starred(self, node: ast.Starred) -> str:
        return f'*{self.visit(node.value)}'

    def generic_visit(self, node: ast.AST) -> NoReturn:
        raise NotImplementedError('Unable to parse %s object' % type(node).__name__)

"""Utilities parsing and analyzing Python code."""

from __future__ import annotations

import ast
import contextlib
import functools
import inspect
import itertools
import operator
import re
import sys
import tokenize
from token import DEDENT, INDENT, NAME, NEWLINE, NUMBER, OP, STRING
from tokenize import COMMENT, NL
from typing import TYPE_CHECKING

from sphinx.pycode.ast import unparse as ast_unparse

if TYPE_CHECKING:
    from inspect import Signature
    from typing import Any

if sys.version_info[:2] >= (3, 12):
    AssignmentLike = ast.Assign | ast.AnnAssign | ast.TypeAlias
    AssignmentLikeType = (ast.Assign, ast.AnnAssign, ast.TypeAlias)
else:
    AssignmentLike = ast.Assign | ast.AnnAssign
    AssignmentLikeType = (ast.Assign, ast.AnnAssign)

comment_re = re.compile('^\\s*#: ?(.*)\r?\n?$')
indent_re = re.compile('^\\s*$')
emptyline_re = re.compile('^\\s*(#.*)?$')


def filter_whitespace(code: str) -> str:
    return code.replace('\f', ' ')  # replace FF (form feed) with whitespace


def get_assign_targets(node: AssignmentLike) -> list[ast.expr]:
    """Get list of targets from AssignmentLike node."""
    if isinstance(node, ast.Assign):
        return node.targets
    elif isinstance(node, ast.AnnAssign):
        return [node.target]
    else:
        return [node.name]  # ast.TypeAlias


def get_lvar_names(node: ast.AST, self: ast.arg | None = None) -> list[str]:
    """Convert assignment-AST to variable names.

    This raises `TypeError` if the assignment does not create new variable::

        ary[0] = 'foo'
        dic['bar'] = 'baz'
        # => TypeError
    """
    if self:
        self_id = self.arg

    node_name = node.__class__.__name__
    if node_name in {'Constant', 'Index', 'Slice', 'Subscript'}:
        raise TypeError('%r does not create new variable' % node)
    if node_name == 'Name':
        if self is None or node.id == self_id:  # type: ignore[attr-defined]
            return [node.id]  # type: ignore[attr-defined]
        else:
            raise TypeError('The assignment %r is not instance variable' % node)
    elif node_name in {'Tuple', 'List'}:
        members = []
        for elt in node.elts:  # type: ignore[attr-defined]
            with contextlib.suppress(TypeError):
                members.extend(get_lvar_names(elt, self))

        return members
    elif node_name == 'Attribute':
        if (
            node.value.__class__.__name__ == 'Name'  # type: ignore[attr-defined]
            and self
            and node.value.id == self_id  # type: ignore[attr-defined]
        ):
            # instance variable
            return ['%s' % get_lvar_names(node.attr, self)[0]]  # type: ignore[attr-defined]
        else:
            raise TypeError('The assignment %r is not instance variable' % node)
    elif node_name == 'str':
        return [node]  # type: ignore[list-item]
    elif node_name == 'Starred':
        return get_lvar_names(node.value, self)  # type: ignore[attr-defined]
    else:
        raise NotImplementedError('Unexpected node name %r' % node_name)


def dedent_docstring(s: str) -> str:
    """Remove common leading indentation from docstring."""

    def dummy() -> None:
        # dummy function to mock `inspect.getdoc`.
        pass

    dummy.__doc__ = s
    docstring = inspect.getdoc(dummy)
    if docstring:
        return docstring.lstrip('\r\n').rstrip('\r\n')
    else:
        return ''


class Token:
    """Better token wrapper for tokenize module."""

    def __init__(
        self,
        kind: int,
        value: Any,
        start: tuple[int, int],
        end: tuple[int, int],
        source: str,
    ) -> None:
        self.kind = kind
        self.value = value
        self.start = start
        self.end = end
        self.source = source

    def __eq__(self, other: object) -> bool:
        if isinstance(other, int):
            return self.kind == other
        elif isinstance(other, str):
            return self.value == other
        elif isinstance(other, (list, tuple)):
            return [self.kind, self.value] == list(other)
        elif other is None:
            return False
        else:
            raise ValueError('Unknown value: %r' % other)

    def __hash__(self) -> int:
        return hash((self.kind, self.value, self.start, self.end, self.source))

    def match(self, *conditions: Any) -> bool:
        return any(self == candidate for candidate in conditions)

    def __repr__(self) -> str:
        return f'<Token kind={tokenize.tok_name[self.kind]!r} value={self.value.strip()!r}>'


class TokenProcessor:
    def __init__(self, buffers: list[str]) -> None:
        lines = iter(buffers)
        self.buffers = buffers
        self.tokens = tokenize.generate_tokens(lambda: next(lines))
        self.current: Token | None = None
        self.previous: Token | None = None

    def get_line(self, lineno: int) -> str:
        """Returns specified line."""
        return self.buffers[lineno - 1]

    def fetch_token(self) -> Token | None:
        """Fetch the next token from source code.

        Returns ``None`` if sequence finished.
        """
        try:
            self.previous = self.current
            self.current = Token(*next(self.tokens))
        except StopIteration:
            self.current = None

        return self.current

    def fetch_until(self, condition: Any) -> list[Token]:
        """Fetch tokens until specified token appeared.

        .. note:: This also handles parenthesis well.
        """
        tokens = []
        while current := self.fetch_token():
            tokens.append(current)
            if current == condition:
                break
            if current == [OP, '(']:
                tokens += self.fetch_until([OP, ')'])
            elif current == [OP, '{']:
                tokens += self.fetch_until([OP, '}'])
            elif current == [OP, '[']:
                tokens += self.fetch_until([OP, ']'])

        return tokens


class AfterCommentParser(TokenProcessor):
    """Python source code parser to pick up comments after assignments.

    This parser takes code which starts with an assignment statement,
    and returns the comment for the variable if one exists.
    """

    def __init__(self, lines: list[str]) -> None:
        super().__init__(lines)
        self.comment: str | None = None

    def fetch_rvalue(self) -> list[Token]:
        """Fetch right-hand value of assignment."""
        tokens = []
        while current := self.fetch_token():
            tokens.append(current)
            if current == [OP, '(']:
                tokens += self.fetch_until([OP, ')'])
            elif current == [OP, '{']:
                tokens += self.fetch_until([OP, '}'])
            elif current == [OP, '[']:
                tokens += self.fetch_until([OP, ']'])
            elif current == INDENT:
                tokens += self.fetch_until(DEDENT)
            elif current == [OP, ';']:  # NoQA: SIM114
                break
            elif current and current.kind not in {OP, NAME, NUMBER, STRING}:
                break

        return tokens

    def parse(self) -> None:
        """Parse the code and obtain comment after assignment."""
        # skip lvalue (or whole of AnnAssign)
        while (tok := self.fetch_token()) and not tok.match(
            [OP, '='], NEWLINE, COMMENT
        ):
            assert tok
        assert tok is not None

        # skip rvalue (if exists)
        if tok == [OP, '=']:
            self.fetch_rvalue()
            tok = self.current
            assert tok is not None

        if tok == COMMENT:
            self.comment = tok.value


class VariableCommentPicker(ast.NodeVisitor):
    """Python source code parser to pick up variable comments."""

    def __init__(self, buffers: list[str], encoding: str) -> None:
        self.counter = itertools.count()
        self.buffers = buffers
        self.encoding = encoding
        self.context: list[str] = []
        self.current_classes: list[str] = []
        self.current_function: ast.FunctionDef | None = None
        self.comments: dict[tuple[str, str], str] = {}
        self.annotations: dict[tuple[str, str], str] = {}
        self.previous: ast.AST | None = None
        self.deforders: dict[str, int] = {}
        self.finals: list[str] = []
        self.overloads: dict[str, list[Signature]] = {}
        self.typing_mods: set[str] = set()
        self.typing_final_names: set[str] = set()
        self.typing_overload_names: set[str] = set()
        super().__init__()

    def get_qualname_for(self, name: str) -> list[str] | None:
        """Get qualified name for given object as a list of string(s)."""
        if self.current_function:
            if self.current_classes and self.context[-1] == '__init__':
                # store variable comments inside __init__ method of classes
                return [*self.context[:-1], name]
            else:
                return None
        else:
            return [*self.context, name]

    def add_entry(self, name: str) -> None:
        qualname = self.get_qualname_for(name)
        if qualname:
            self.deforders['.'.join(qualname)] = next(self.counter)

    def add_final_entry(self, name: str) -> None:
        qualname = self.get_qualname_for(name)
        if qualname:
            self.finals.append('.'.join(qualname))

    def add_overload_entry(self, func: ast.FunctionDef) -> None:
        # avoid circular import problem
        from sphinx.util.inspect import signature_from_ast

        qualname = self.get_qualname_for(func.name)
        if qualname:
            overloads = self.overloads.setdefault('.'.join(qualname), [])
            overloads.append(signature_from_ast(func))

    def add_variable_comment(self, name: str, comment: str) -> None:
        qualname = self.get_qualname_for(name)
        if qualname:
            basename = '.'.join(qualname[:-1])
            self.comments[basename, name] = comment

    def add_variable_annotation(self, name: str, annotation: ast.AST) -> None:
        qualname = self.get_qualname_for(name)
        if qualname:
            basename = '.'.join(qualname[:-1])
            self.annotations[basename, name] = ast_unparse(annotation)

    def is_final(self, decorators: list[ast.expr]) -> bool:
        final = {f'{modname}.final' for modname in self.typing_mods}
        final |= self.typing_final_names

        for decorator in decorators:
            try:
                if ast_unparse(decorator) in final:
                    return True
            except NotImplementedError:
                pass

        return False

    def is_overload(self, decorators: list[ast.expr]) -> bool:
        overload = {f'{modname}.overload' for modname in self.typing_mods}
        overload |= self.typing_overload_names

        for decorator in decorators:
            try:
                if ast_unparse(decorator) in overload:
                    return True
            except NotImplementedError:
                pass

        return False

    def get_self(self) -> ast.arg | None:
        """Returns the name of the first argument if in a function."""
        if self.current_function and self.current_function.args.args:
            return self.current_function.args.args[0]
        if self.current_function and self.current_function.args.posonlyargs:
            return self.current_function.args.posonlyargs[0]
        return None

    def get_line(self, lineno: int) -> str:
        """Returns specified line."""
        return self.buffers[lineno - 1]

    def _handle_assignment(self, node: ast.Assign | ast.AnnAssign) -> None:
        """Handles Assign node and pick up a variable comment."""
        try:
            targets = get_assign_targets(node)
            varnames: list[str] = functools.reduce(
                operator.iadd,
                [get_lvar_names(t, self=self.get_self()) for t in targets],
                [],
            )
            current_line = self.get_line(node.lineno)
        except TypeError:
            return  # this assignment is not new definition!

        # record annotation
        if hasattr(node, 'annotation') and node.annotation:
            for varname in varnames:
                self.add_variable_annotation(varname, node.annotation)
        elif hasattr(node, 'type_comment') and node.type_comment:
            for varname in varnames:
                self.add_variable_annotation(varname, node.type_comment)  # type: ignore[arg-type]
        self._collect_doc_comment(node, varnames, current_line)

    def _collect_doc_comment(
        self,
        node: AssignmentLike,
        varnames: list[str],
        current_line: str,
    ) -> None:
        # check comments after assignment
        parser = AfterCommentParser([
            current_line[node.col_offset :],
            *self.buffers[node.lineno :],
        ])
        parser.parse()
        if parser.comment and comment_re.match(parser.comment):
            for varname in varnames:
                self.add_variable_comment(
                    varname, comment_re.sub('\\1', parser.comment)
                )
                self.add_entry(varname)
            return

        # check comments before assignment
        if indent_re.match(current_line[: node.col_offset]):
            comment_lines = []
            for i in range(node.lineno - 1):
                before_line = self.get_line(node.lineno - 1 - i)
                if comment_re.match(before_line):
                    comment_lines.append(comment_re.sub('\\1', before_line))
                else:
                    break

            if comment_lines:
                comment = dedent_docstring('\n'.join(reversed(comment_lines)))
                for varname in varnames:
                    self.add_variable_comment(varname, comment)
                    self.add_entry(varname)
                return

        # not commented (record deforders only)
        for varname in varnames:
            self.add_entry(varname)

    def visit(self, node: ast.AST) -> None:
        """Updates self.previous to the given node."""
        super().visit(node)
        self.previous = node

    def visit_Import(self, node: ast.Import) -> None:
        """Handles Import node and record the order of definitions."""
        for name in node.names:
            self.add_entry(name.asname or name.name)

            if name.name in {'typing', 'typing_extensions'}:
                self.typing_mods.add(name.asname or name.name)
            elif name.name in {'typing.final', 'typing_extensions.final'}:
                self.typing_final_names.add(name.asname or name.name)
            elif name.name in {'typing.overload', 'typing_extensions.overload'}:
                self.typing_overload_names.add(name.asname or name.name)

    def visit_ImportFrom(self, node: ast.ImportFrom) -> None:
        """Handles Import node and record the order of definitions."""
        for name in node.names:
            self.add_entry(name.asname or name.name)

            if node.module not in {'typing', 'typing_extensions'}:
                continue
            if name.name == 'final':
                self.typing_final_names.add(name.asname or name.name)
            elif name.name == 'overload':
                self.typing_overload_names.add(name.asname or name.name)

    def visit_Assign(self, node: ast.Assign) -> None:
        """Handles Assign node and pick up a variable comment."""
        self._handle_assignment(node)

    def visit_AnnAssign(self, node: ast.AnnAssign) -> None:
        """Handles AnnAssign node and pick up a variable comment."""
        self._handle_assignment(node)

    def visit_Expr(self, node: ast.Expr) -> None:
        """Handles Expr node and pick up a comment if string."""
        if (
            isinstance(self.previous, AssignmentLikeType)
            and isinstance(node.value, ast.Constant)
            and isinstance(node.value.value, str)
        ):
            try:
                targets = get_assign_targets(self.previous)
                varnames = get_lvar_names(targets[0], self.get_self())
                for varname in varnames:
                    if isinstance(node.value.value, str):
                        docstring = node.value.value
                    else:
                        docstring = node.value.value.decode(self.encoding or 'utf-8')

                    self.add_variable_comment(varname, dedent_docstring(docstring))
                    self.add_entry(varname)
            except TypeError:
                pass  # this assignment is not new definition!

    def visit_Try(self, node: ast.Try) -> None:
        """Handles Try node and processes body and else-clause.

        .. note:: pycode parser ignores objects definition in except-clause.
        """
        for subnode in node.body:
            self.visit(subnode)
        for subnode in node.orelse:
            self.visit(subnode)

    def visit_ClassDef(self, node: ast.ClassDef) -> None:
        """Handles ClassDef node and set context."""
        self.current_classes.append(node.name)
        self.add_entry(node.name)
        if self.is_final(node.decorator_list):
            self.add_final_entry(node.name)
        self.context.append(node.name)
        self.previous = node
        for child in node.body:
            self.visit(child)
        self.context.pop()
        self.current_classes.pop()

    def visit_FunctionDef(self, node: ast.FunctionDef) -> None:
        """Handles FunctionDef node and set context."""
        if self.current_function is None:
            # should be called before setting self.current_function
            self.add_entry(node.name)
            if self.is_final(node.decorator_list):
                self.add_final_entry(node.name)
            if self.is_overload(node.decorator_list):
                self.add_overload_entry(node)
            self.context.append(node.name)
            self.current_function = node
            for child in node.body:
                self.visit(child)
            self.context.pop()
            self.current_function = None

    def visit_AsyncFunctionDef(self, node: ast.AsyncFunctionDef) -> None:
        """Handles AsyncFunctionDef node and set context."""
        self.visit_FunctionDef(node)  # type: ignore[arg-type]

    def visit_TypeAlias(self, node: ast.TypeAlias) -> None:  # type: ignore[name-defined]
        """Handles TypeAlias node and picks up a variable comment.

        .. note:: TypeAlias node refers to `type Foo = Bar` (PEP 695) assignment,
                  NOT `Foo: TypeAlias = Bar` (PEP 613).
        """
        # Python 3.12+
        current_line = self.get_line(node.lineno)
        self._collect_doc_comment(node, [node.name.id], current_line)


class DefinitionFinder(TokenProcessor):
    """Python source code parser to detect location of functions,
    classes and methods.
    """

    def __init__(self, lines: list[str]) -> None:
        super().__init__(lines)
        self.decorator: Token | None = None
        self.context: list[str] = []
        self.indents: list[tuple[str, str | None, int | None]] = []
        self.definitions: dict[str, tuple[str, int, int]] = {}

    def add_definition(self, name: str, entry: tuple[str, int, int]) -> None:
        """Add a location of definition."""
        if self.indents and self.indents[-1][0] == entry[0] == 'def':
            # ignore definition of inner function
            pass
        else:
            self.definitions[name] = entry

    def parse(self) -> None:
        """Parse the code to obtain location of definitions."""
        while True:
            token = self.fetch_token()
            if token is None:
                break
            if token == COMMENT:
                pass
            elif token == [OP, '@'] and (
                self.previous is None
                or self.previous.match(NEWLINE, NL, INDENT, DEDENT)
            ):
                if self.decorator is None:
                    self.decorator = token
            elif token.match([NAME, 'class']):
                self.parse_definition('class')
            elif token.match([NAME, 'def']):
                self.parse_definition('def')
            elif token == INDENT:
                self.indents.append(('other', None, None))
            elif token == DEDENT:
                self.finalize_block()

    def parse_definition(self, typ: str) -> None:
        """Parse AST of definition."""
        name = self.fetch_token()
        self.context.append(name.value)  # type: ignore[union-attr]
        funcname = '.'.join(self.context)

        if self.decorator:
            start_pos = self.decorator.start[0]
            self.decorator = None
        else:
            start_pos = name.start[0]  # type: ignore[union-attr]

        self.fetch_until([OP, ':'])
        if self.fetch_token().match(COMMENT, NEWLINE):  # type: ignore[union-attr]
            self.fetch_until(INDENT)
            self.indents.append((typ, funcname, start_pos))
        else:
            # one-liner
            self.add_definition(funcname, (typ, start_pos, name.end[0]))  # type: ignore[union-attr]
            self.context.pop()

    def finalize_block(self) -> None:
        """Finalize definition block."""
        definition = self.indents.pop()
        if definition[0] != 'other':
            typ, funcname, start_pos = definition
            end_pos = self.current.end[0] - 1  # type: ignore[union-attr]
            while emptyline_re.match(self.get_line(end_pos)):
                end_pos -= 1

            self.add_definition(funcname, (typ, start_pos, end_pos))  # type: ignore[arg-type]
            self.context.pop()


class Parser:
    """Python source code parser to pick up variable comments.

    This is a better wrapper for ``VariableCommentPicker``.
    """

    def __init__(self, code: str, encoding: str = 'utf-8') -> None:
        self.code = filter_whitespace(code)
        self.encoding = encoding
        self.annotations: dict[tuple[str, str], str] = {}
        self.comments: dict[tuple[str, str], str] = {}
        self.deforders: dict[str, int] = {}
        self.definitions: dict[str, tuple[str, int, int]] = {}
        self.finals: list[str] = []
        self.overloads: dict[str, list[Signature]] = {}

    def parse(self) -> None:
        """Parse the source code."""
        self.parse_comments()
        self.parse_definition()

    def parse_comments(self) -> None:
        """Parse the code and pick up comments."""
        tree = ast.parse(self.code, type_comments=True)
        picker = VariableCommentPicker(self.code.splitlines(True), self.encoding)
        picker.visit(tree)
        self.annotations = picker.annotations
        self.comments = picker.comments
        self.deforders = picker.deforders
        self.finals = picker.finals
        self.overloads = picker.overloads

    def parse_definition(self) -> None:
        """Parse the location of definitions from the code."""
        parser = DefinitionFinder(self.code.splitlines(True))
        parser.parse()
        self.definitions = parser.definitions
